import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`jsonpath.zh`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<h2>语法</h2><p>根据所使用的客户端不同，JSONPath 表达式可以以 <code>$.</code> 开头表示根元素。 有些客户端会省略开头的 <code>$.</code>。</p><table><thead><tr><th>语法</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td><code>$.store.book[0].title</code></td><td style="text-align:left;"></td></tr><tr><td><code>store.book[0].title</code></td><td style="text-align:left;">隐式的 <code>$.</code></td></tr><tr><td><code>$[&#39;store&#39;][&#39;book&#39;][0][&#39;title&#39;]</code></td><td style="text-align:left;">类似脚本语言的替代记法</td></tr></tbody></table><h2>树遍历</h2><table><thead><tr><th>语法</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td><code>$.parentNode.childNode.field</code></td><td style="text-align:left;">XPath: <code>/parentNode/childNode/@field</code>（“parentNode” 下所有 “childNode” 的 “field” 内容）</td></tr><tr><td><code>$..anyChildNode</code></td><td style="text-align:left;">XPath: <code>//anyChildNode</code>（任意深度下所有名为 “anyChildNode” 的子节点）</td></tr><tr><td><code>$.parentNode.*</code></td><td style="text-align:left;">XPath: <code>/parentNode/*</code>（所有下级子节点）</td></tr></tbody></table><h2>数组访问</h2><table><thead><tr><th>语法</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td><code>$.myList[0]</code></td><td style="text-align:left;">第一个元素</td></tr><tr><td><code>$.myList[-1]</code></td><td style="text-align:left;">最后一个元素</td></tr><tr><td><code>$.myList[2:3]</code></td><td style="text-align:left;">范围</td></tr><tr><td><code>$.myList[0,4,5]</code></td><td style="text-align:left;">选择</td></tr></tbody></table><h2>过滤</h2><table><thead><tr><th>语法</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td><code>$.customer[?(@.car)]</code></td><td style="text-align:left;">仅包含拥有 “car” 属性的 “customer”</td></tr><tr><td><code>$.customer[?(@.car == &#39;Ford Fiesta&#39;)]</code></td><td style="text-align:left;">仅包含拥有 “Ford Fiesta” 的 “customer”</td></tr><tr><td><code>$.customer[?(@.age &gt; 18)]</code></td><td style="text-align:left;">仅包含成年人</td></tr></tbody></table><h2>复杂条件</h2><table><thead><tr><th>语法</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td><code>$.customer[?(@.age &gt; 18 || @.car == &#39;Ford Fiesta&#39;)]</code></td><td style="text-align:left;">逻辑或</td></tr><tr><td><code>$.customer[?(@.age &lt; 18 &amp;&amp; @.hobby == &#39;Biking&#39; )]</code></td><td style="text-align:left;">逻辑与</td></tr></tbody></table><h2>输出映射</h2><table><thead><tr><th>语法</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td><code>$.[].{Name:name, Age:age, Hobbies:details.hobbies}</code></td><td style="text-align:left;">将字段/嵌套字段映射到新集合</td></tr></tbody></table><h2>致谢</h2><p>原作者：<a href="https://gist.github.com/mackoj/5786f8b95da0a82e8e003f444c4295bf">https://gist.github.com/mackoj/5786f8b95da0a82e8e003f444c4295bf</a></p>`,15)]]))}};export{a as default};